//! New persisted workflows participate in the existing workspace-switch gate.
use crate::Res;use std::path::Path;use serde_json::Value;
pub(crate) fn active(root:&Path)->Res<bool>{for folder in ["operation-jobs","new-product-jobs"]{let directory=root.join(folder);if !directory.is_dir(){continue}for entry in std::fs::read_dir(&directory).map_err(|_|"TASK_STORAGE_UNAVAILABLE")?{let entry=entry.map_err(|_|"TASK_STORAGE_UNAVAILABLE")?;if !entry.file_type().map_err(|_|"TASK_STORAGE_UNAVAILABLE")?.is_file(){continue}let path=entry.path();let Some(id)=path.file_stem().and_then(|s|s.to_str()).filter(|s|uuid::Uuid::parse_str(s).is_ok())else{continue};if path.extension().is_some_and(|e|e=="planning"){if !directory.join(format!("{id}.cancel")).exists()&&entry.metadata().and_then(|m|m.modified()).ok().and_then(|t|t.elapsed().ok()).is_some_and(|age|age.as_secs()<120){return Ok(true)}continue}if !path.extension().is_some_and(|e|e=="json"){continue}let value:Value=serde_json::from_slice(&std::fs::read(path).map_err(|_|"TASK_STORAGE_UNAVAILABLE")?).map_err(|_|"TASK_STORAGE_UNAVAILABLE")?;let state=value["state"].as_str().or(value["status"].as_str()).ok_or("TASK_STORAGE_UNAVAILABLE")?;if !matches!(state,"done"|"completed"|"partial"|"failed"|"cancelled"|"attention"){return Ok(true)}}}Ok(false)}
#[cfg(test)]mod tests{use super::*;use serde_json::json;
 #[test]fn standard_new_product_and_planning_are_included_without_blocking_finished_history(){let temp=tempfile::tempdir().unwrap();for folder in ["operation-jobs","new-product-jobs"]{let dir=temp.path().join(folder);std::fs::create_dir_all(&dir).unwrap();let id=uuid::Uuid::new_v4().to_string();let path=dir.join(format!("{id}.json"));std::fs::write(&path,json!({"state":"waiting"}).to_string()).unwrap();assert!(active(temp.path()).unwrap());std::fs::write(&path,json!({"state":"done"}).to_string()).unwrap();assert!(!active(temp.path()).unwrap());}let dir=temp.path().join("operation-jobs");let id=uuid::Uuid::new_v4().to_string();std::fs::write(dir.join(format!("{id}.planning")),b"planning").unwrap();assert!(active(temp.path()).unwrap());std::fs::write(dir.join(format!("{id}.cancel")),b"stop").unwrap();assert!(!active(temp.path()).unwrap());}
}
